"""Independent reference model for the layered receive/canonical-wire contract (v3.0)."""
import hashlib, json

MAX62=(1<<62)-1
MAXSTREAMS=1<<60
LEVELS=['I','H','A']

def venc(x):
    w=next(w for w in (1,2,4,8) if x<2**(8*w-2))
    return (([1,2,4,8].index(w)<<(8*w-2))|x).to_bytes(w,'big')

def sha(b): return hashlib.sha256(b).hexdigest()

class Err(Exception):
    def __init__(self,code,offset): self.code=code; self.offset=offset

class Rd:
    def __init__(self,d,p,fs): self.d=d; self.p=p; self.fs=fs
    def vi(self):
        if self.p>=len(self.d): raise Err('FRAME_ENCODING_ERROR',self.fs)
        b=self.d[self.p]; self.p+=1
        w=1<<(b>>6)
        if w-1>len(self.d)-self.p: raise Err('FRAME_ENCODING_ERROR',self.fs)
        val=b&0x3f
        for i in range(1,w): val=(val<<8)|self.d[self.p+i]
        self.p+=w-1
        return val
    def one(self):
        if self.p>=len(self.d): raise Err('FRAME_ENCODING_ERROR',self.fs)
        b=self.d[self.p]; self.p+=1; return b
    def take(self,n):
        if n<0 or n>len(self.d)-self.p: raise Err('FRAME_ENCODING_ERROR',self.fs)
        r=self.d[self.p:self.p+n]; self.p+=n; return r
    def rest(self): return self.take(len(self.d)-self.p)

KNOWN=set(list(range(0x00,0x1f))+[0x30,0x31])
APPONLY=set([0x04,0x05]+list(range(0x08,0x18))+[0x18,0x19,0x1a,0x1b,0x1d,0x30,0x31])

class Frame: pass

def parse_frame(d,p,level):
    fs=p
    b0=d[p]; w=1<<(b0>>6)
    if w>len(d)-p: raise Err('FRAME_ENCODING_ERROR',fs)
    t=b0&0x3f
    for i in range(1,w): t=(t<<8)|d[p+i]
    if w!=1 or t not in KNOWN: raise Err('FRAME_ENCODING_ERROR',fs)
    if t in (0x07,0x1e): raise Err('PROTOCOL_VIOLATION',fs)
    if level!=2 and t in APPONLY: raise Err('PROTOCOL_VIOLATION',fs)
    f=Frame(); f.type=t
    c=Rd(d,p+w,fs)
    if t in (0x00,0x01): pass
    elif t in (0x02,0x03):
        f.largest=c.vi(); f.delay=c.vi(); f.count=c.vi(); f.first=c.vi()
        if f.first>f.largest: raise Err('FRAME_ENCODING_ERROR',fs)
        low=f.largest-f.first
        f.pairs=[]
        for _ in range(f.count):
            gap=c.vi(); rng=c.vi()
            if low<gap+2: raise Err('FRAME_ENCODING_ERROR',fs)
            high=low-gap-2
            if rng>high: raise Err('FRAME_ENCODING_ERROR',fs)
            f.pairs.append((gap,rng)); low=high-rng
        if t==0x03: f.ecn=(c.vi(),c.vi(),c.vi())
    elif t==0x04: f.sid=c.vi(); f.err=c.vi(); f.final=c.vi()
    elif t==0x05: f.sid=c.vi(); f.err=c.vi()
    elif t==0x06:
        f.off=c.vi(); f.ln=c.vi(); f.data=c.take(f.ln)
        if f.off+f.ln>MAX62: raise Err('FRAME_ENCODING_ERROR',fs)
    elif 0x08<=t<=0x0f:
        f.off_flag=bool(t&4); f.len_flag=bool(t&2); f.fin=bool(t&1)
        f.sid=c.vi(); f.off=c.vi() if f.off_flag else 0
        if f.len_flag: f.ln=c.vi(); f.data=c.take(f.ln)
        else: f.data=c.rest(); f.ln=len(f.data)
    elif t in (0x10,0x12,0x13,0x14,0x16,0x17,0x19):
        f.v=c.vi()
        if t in (0x12,0x13,0x16,0x17) and f.v>MAXSTREAMS: raise Err('FRAME_ENCODING_ERROR',fs)
    elif t in (0x11,0x15): f.sid=c.vi(); f.v=c.vi()
    elif t==0x18:
        f.seq=c.vi(); f.rpt=c.vi()
        if f.rpt>f.seq: raise Err('FRAME_ENCODING_ERROR',fs)
        f.cidlen=c.one()
        if f.cidlen<1 or f.cidlen>20: raise Err('FRAME_ENCODING_ERROR',fs)
        f.cid=c.take(f.cidlen); f.token=c.take(16)
    elif t in (0x1a,0x1b): f.data=c.take(8)
    elif t==0x1c: f.err=c.vi(); f.trig=c.vi(); f.rlen=c.vi(); f.data=c.take(f.rlen)
    elif t==0x1d: f.err=c.vi(); f.rlen=c.vi(); f.data=c.take(f.rlen)
    elif t==0x30: f.data=c.rest()
    elif t==0x31: f.ln=c.vi(); f.data=c.take(f.ln)
    f.end=c.p
    return f

def encode_frame(f):
    t=f.type
    if t==0x00: return b'\x00'
    if t==0x01: return b'\x01'
    if t in (0x02,0x03):
        out=venc(t)+venc(f.largest)+venc(f.delay)+venc(f.count)+venc(f.first)
        for g,r in f.pairs: out+=venc(g)+venc(r)
        if t==0x03: out+=venc(f.ecn[0])+venc(f.ecn[1])+venc(f.ecn[2])
        return out
    if t==0x04: return venc(4)+venc(f.sid)+venc(f.err)+venc(f.final)
    if t==0x05: return venc(5)+venc(f.sid)+venc(f.err)
    if t==0x06: return venc(6)+venc(f.off)+venc(f.ln)+f.data
    if 0x08<=t<=0x0f:
        out=venc(t)+venc(f.sid)
        if f.off_flag: out+=venc(f.off)
        if f.len_flag: out+=venc(f.ln)
        return out+f.data
    if t==0x10: return venc(0x10)+venc(f.v)
    if t in (0x11,0x15): return venc(t)+venc(f.sid)+venc(f.v)
    if t in (0x12,0x13,0x14,0x16,0x17,0x19): return venc(t)+venc(f.v)
    if t==0x18: return venc(0x18)+venc(f.seq)+venc(f.rpt)+bytes([f.cidlen])+f.cid+f.token
    if t in (0x1a,0x1b): return venc(t)+f.data
    if t==0x1c: return venc(0x1c)+venc(f.err)+venc(f.trig)+venc(f.rlen)+f.data
    if t==0x1d: return venc(0x1d)+venc(f.err)+venc(f.rlen)+f.data
    if t==0x30: return b'\x30'+f.data
    if t==0x31: return venc(0x31)+venc(f.ln)+f.data
    raise AssertionError(t)

class Store:
    def __init__(self,segs=None): self.segs=list(segs) if segs else []
    def insert(self,lo,data,fs):
        if not data: return
        hi=lo+len(data)
        overlap=[s for s in self.segs if s[0]<hi and s[0]+len(s[1])>lo]
        for st,b in overlap:
            a=max(st,lo); bnd=min(st+len(b),hi)
            for p in range(a,bnd):
                if b[p-st]!=data[p-lo]: raise Err('PROTOCOL_VIOLATION',fs)
        added=[]; cur=lo
        for st,b in overlap:
            if st>cur: added.append((cur,data[cur-lo:st-lo]))
            cur=max(cur,st+len(b))
        if cur<hi: added.append((cur,data[cur-lo:]))
        self.segs=sorted(self.segs+added)
    def merged(self):
        out=[]
        for st,b in self.segs:
            if out and st<=out[-1][1]: out[-1][1]=max(out[-1][1],st+len(b))
            else: out.append([st,st+len(b)])
        return out
    def unique(self): return sum(len(b) for _,b in self.segs)
    def prefix(self):
        m=self.merged()
        return m[0][1] if m and m[0][0]==0 else 0
    def prefix_bytes(self):
        p=self.prefix(); out=bytearray()
        for st,b in self.segs:
            if st>=p: break
            out+=b
        return bytes(out[:p])

class Stream:
    def __init__(self,sid):
        self.id=sid; self.high=0; self.sendmax=0; self.final=None; self.reset=None; self.stop=None
        self.bytes=Store()

class Trace:
    def __init__(self,tr):
        self.lim_conn=tr['limits']['connection']; self.lim_stream=tr['limits']['stream']
        self.lim_bidi=tr['limits']['bidi']; self.lim_uni=tr['limits']['uni']; self.lim_cids=tr['limits']['cids']
        self.local_bidi=tr['local']['bidi']; self.local_uni=tr['local']['uni']
        self.local=[bytes.fromhex(x) for x in tr['local']['cids']]
        self.cidw=len(self.local[0])
        self.peer=bytes.fromhex(tr['peer']['cid']); self.peertok=bytes.fromhex(tr['peer']['token'])
        self.seeds=tr['received']; self.events=tr['events']
        self.keys={'I':True,'H':False,'A':False}
        self.closed=None
        self.largest={'I':None,'H':None,'A':None}
        self.seen={'I':set(),'H':set(),'A':set()}
        self.ack={'I':[],'H':[],'A':[]}
        self.ecn={'I':[0,0,0],'H':[0,0,0],'A':[0,0,0]}
        self.crypto={l:Store() for l in LEVELS}
        self.streams={}
        self.open_bidi=0; self.open_uni=0; self.used=0
        self.smd=0; self.sms=[0,0]
        self.peermap={0:(self.peer,self.peertok)}
        self.rpt=0; self.active=1
        self.retired=set()
        self.epochs={}
        self.cur=0
        self.packets=[]; self.datagrams=[]
        for l in LEVELS:
            if self.seeds[l] is not None:
                self.seen[l].add(self.seeds[l]); self.largest[l]=self.seeds[l]
        if self.seeds['A'] is not None:
            self.epochs[0]=[self.seeds['A'],self.seeds['A'],1]

    # ---------------- transaction snapshot
    def snap(self):
        return dict(keys=dict(self.keys),closed=self.closed,largest=dict(self.largest),
            seen={k:set(v) for k,v in self.seen.items()},ack={k:list(v) for k,v in self.ack.items()},
            ecn={k:list(v) for k,v in self.ecn.items()},
            crypto={l:Store(list(self.crypto[l].segs)) for l in LEVELS},
            streams={sid:(s.high,s.sendmax,s.final,s.reset,s.stop,Store(list(s.bytes.segs))) for sid,s in self.streams.items()},
            open_bidi=self.open_bidi,open_uni=self.open_uni,used=self.used,smd=self.smd,sms=list(self.sms),
            peermap={k:v for k,v in self.peermap.items()},rpt=self.rpt,active=self.active,retired=set(self.retired),
            epochs={k:list(v) for k,v in self.epochs.items()},cur=self.cur)
    def restore(self,s):
        self.keys=dict(s['keys']); self.closed=s['closed']; self.largest=dict(s['largest'])
        self.seen={k:set(v) for k,v in s['seen'].items()}; self.ack={k:list(v) for k,v in s['ack'].items()}
        self.ecn={k:list(v) for k,v in s['ecn'].items()}
        self.crypto={l:Store(list(s['crypto'][l].segs)) for l in LEVELS}
        self.streams={}
        for sid,(high,sendmax,fin,rst,stp,st) in s['streams'].items():
            n=Stream(sid); n.high=high; n.sendmax=sendmax; n.final=fin; n.reset=rst; n.stop=stp; n.bytes=Store(list(st.segs))
            self.streams[sid]=n
        self.open_bidi=s['open_bidi']; self.open_uni=s['open_uni']; self.used=s['used']; self.smd=s['smd']
        self.sms=list(s['sms']); self.peermap={k:v for k,v in s['peermap'].items()}; self.rpt=s['rpt']
        self.active=s['active']; self.retired=set(s['retired'])
        self.epochs={k:list(v) for k,v in s['epochs'].items()}; self.cur=s['cur']

    # ---------------- header framing
    def header(self,w,pos):
        b0=w[pos]
        if b0&0x80:
            if 0xc0<=b0<=0xc3: lvl=0
            elif 0xe0<=b0<=0xe3: lvl=1
            else: return None
            pnw=(b0&3)+1; p=pos+1
            if len(w)-p<4: return None
            if w[p:p+4]!=b'\0\0\0\1': return None
            p+=4
            if p>=len(w): return None
            dl=w[p]; p+=1
            if dl>20 or len(w)-p<dl: return None
            dcid=w[p:p+dl]; p+=dl
            if p>=len(w): return None
            sl=w[p]; p+=1
            if sl>20 or len(w)-p<sl: return None
            scid=w[p:p+sl]; p+=sl
            token=b''
            if lvl==0:
                r=self.varint(w,p)
                if r is None: return None
                tl,p=r
                if tl>len(w)-p: return None
                token=w[p:p+tl]; p+=tl
            r=self.varint(w,p)
            if r is None: return None
            ln,p=r
            if ln<pnw or ln>len(w)-p: return None
            raw=0
            for i in range(pnw): raw=(raw<<8)|w[p+i]
            p+=pnw
            payload=w[p:p+(ln-pnw)]; p+=ln-pnw
            return dict(level=lvl,dcid=dcid,scid=scid,token=token,pnw=pnw,raw=raw,payload=payload,end=p,phase=0)
        if not (b0&0x40) or (b0&0x18): return None
        lvl=2; phase=(b0>>2)&1; pnw=(b0&3)+1; p=pos+1
        if len(w)-p<self.cidw: return None
        dcid=w[p:p+self.cidw]; p+=self.cidw
        if len(w)-p<pnw: return None
        raw=0
        for i in range(pnw): raw=(raw<<8)|w[p+i]
        p+=pnw
        return dict(level=lvl,dcid=dcid,scid=b'',token=b'',pnw=pnw,raw=raw,payload=w[p:],end=len(w),phase=phase)

    @staticmethod
    def varint(w,p):
        if p>=len(w): return None
        b=w[p]; wd=1<<(b>>6)
        if wd>len(w)-p: return None
        val=b&0x3f
        for i in range(1,wd): val=(val<<8)|w[p+i]
        return val,p+wd

    @staticmethod
    def reconstruct(raw,width,expected):
        m=1<<(8*width)
        k=(expected-raw)//m
        if k<0: k=0
        low=raw+k*m; high=low+m
        return high if (high-expected)<=abs(expected-low) else low

    def expected(self,level):
        l=self.largest[LEVELS[level]]
        return 0 if l is None else l+1

    def route(self,dcid):
        if len(dcid)!=self.cidw: return -1
        for i,c in enumerate(self.local):
            if c==dcid: return -1 if i in self.retired else i
        return -1

    # ---------------- main
    def run(self):
        for ev,e in enumerate(self.events):
            if 'keys' in e:
                if self.closed is None:
                    for k in LEVELS: self.keys[k]=False
                    for k in e['keys']: self.keys[k]=True
                continue
            self.datagram(ev,e)
        return self.output()

    def datagram(self,ev,e):
        wire=bytes.fromhex(e['datagram']['wire']); auth=e['datagram']['auth']
        pos=0; attempt=0; buf=b''; accepted=0; packets=0
        while pos<len(wire):
            start=pos
            env=self.header(wire,start)
            if env is None:
                self.packets.append(dict(event=ev,packet=attempt,offset=start,level=None,pn=None,epoch=None,status='BAD_HEADER',sha256=None))
                packets=attempt+1
                break
            packets=attempt+1
            ann=auth[attempt] if attempt<len(auth) else None
            canon,ok,epoch,pn,level=self.packet(ev,attempt,env,ann)
            if canon is not None:
                buf+=canon; accepted+=1
            attempt+=1; pos=env['end']
            if env['level']==2: break
        self.datagrams.append(dict(event=ev,packets=packets,accepted=accepted,bytes=len(buf),sha256=sha(buf)))

    def packet(self,ev,pkt,env,ann):
        level=env['level']; L=LEVELS[level]
        pn=self.reconstruct(env['raw'],env['pnw'],self.expected(level))
        def row(status,epoch=None,h=None):
            self.packets.append(dict(event=ev,packet=pkt,offset=env['off'],level=L,pn=pn,epoch=epoch,status=status,sha256=h))
            return h,epoch
        if self.closed is not None:
            row('CLOSED'); return None,False,None,pn,level
        dcidseq=self.route(env['dcid'])
        if dcidseq<0:
            row('DROP_CID'); return None,False,None,pn,level
        if not self.keys[L]:
            row('NO_KEY'); return None,False,None,pn,level
        if pn>MAX62:
            row('PN_RANGE'); return None,False,None,pn,level
        epoch=None
        if level!=2:
            if ann is None or ann!=0:
                row('AUTH'); return None,False,None,pn,level
        else:
            if ann is None:
                row('AUTH'); return None,False,None,pn,level
            okwindow = (ann==self.cur) or (ann+1==self.cur) or (ann==self.cur+1 and self.cur+1<=MAX62)
            if not okwindow or (ann&1)!=(env['phase']&1):
                row('AUTH'); return None,False,None,pn,level
            epoch=ann
        if pn in self.seen[L]:
            row('DUPLICATE',epoch); return None,False,epoch,pn,level
        if level==2:
            for e,st in self.epochs.items():
                if e==epoch: continue
                if (epoch>e and pn<=st[1]) or (epoch<e and pn>=st[0]):
                    self.close('KEY_UPDATE_ERROR',0,ev,pkt)
                    row('KEY_UPDATE_ERROR',epoch); return None,False,epoch,pn,level
        before=self.expected(level)
        snap=self.snap()
        frames=[]
        try:
            peerclose,coff=self.frames(env,dcidseq,frames)
            self.accept(level,pn,epoch)
        except Err as ex:
            self.restore(snap)
            self.close(ex.code,ex.offset,ev,pkt)
            row(ex.code,epoch); return None,False,epoch,pn,level
        if peerclose: self.close('PEER_CLOSE',coff,ev,pkt)
        canon=self.canonical(env,pn,before,frames)
        row('PEER_CLOSE' if peerclose else 'OK',epoch,sha(canon))
        return canon,True,epoch,pn,level

    def close(self,code,offset,ev,pkt):
        if self.closed is not None: return
        self.closed=dict(event=ev,packet=pkt,offset=offset,code=code)

    def accept(self,level,pn,epoch):
        L=LEVELS[level]
        self.seen[L].add(pn)
        if self.largest[L] is None or pn>self.largest[L]: self.largest[L]=pn
        if level==2:
            st=self.epochs.get(epoch)
            if st is None: self.epochs[epoch]=[pn,pn,1]
            else:
                st[0]=min(st[0],pn); st[1]=max(st[1],pn); st[2]+=1
            if epoch==self.cur+1: self.cur=epoch

    def frames(self,env,dcidseq,frames):
        payload=env['payload']
        if not payload: raise Err('FRAME_ENCODING_ERROR',0)
        p=0
        while p<len(payload):
            fs=p
            f=parse_frame(payload,p,env['level'])
            frames.append(f)
            self.apply(f,env['level'],fs,dcidseq)
            p=f.end
            if f.type in (0x1c,0x1d): return True,fs
        return False,0

    def resolve(self,sid,receive,fs):
        cat=sid&3; index=sid>>2
        if cat==0:
            if index>=self.lim_bidi: raise Err('STREAM_LIMIT_ERROR',fs)
            self.open_bidi=max(self.open_bidi,index+1)
        elif cat==1:
            if index>=self.local_bidi: raise Err('STREAM_STATE_ERROR',fs)
        elif cat==2:
            if not receive: raise Err('STREAM_STATE_ERROR',fs)
            if index>=self.lim_uni: raise Err('STREAM_LIMIT_ERROR',fs)
            self.open_uni=max(self.open_uni,index+1)
        else:
            if receive or index>=self.local_uni: raise Err('STREAM_STATE_ERROR',fs)
        if sid not in self.streams: self.streams[sid]=Stream(sid)
        return self.streams[sid]

    def apply(self,f,level,fs,dcidseq):
        t=f.type
        if t in (0x00,0x01): return
        if t in (0x02,0x03):
            L=LEVELS[level]
            low=f.largest-f.first
            self.ack[L].append((low,f.largest+1))
            for gap,rng in f.pairs:
                high=low-gap-2; low=high-rng
                self.ack[L].append((low,high+1))
            if t==0x03:
                for i in range(3):
                    self.ecn[L][i]=max(self.ecn[L][i],f.ecn[i])
            return
        if t==0x06:
            self.crypto[LEVELS[level]].insert(f.off,f.data,fs); return
        if 0x08<=t<=0x0f:
            s=self.resolve(f.sid,True,fs)
            end=f.off+f.ln
            if end>MAX62: raise Err('FRAME_ENCODING_ERROR',fs)
            if s.final is not None:
                if end>s.final or (f.fin and end!=s.final): raise Err('FINAL_SIZE_ERROR',fs)
            elif f.fin and end<s.high: raise Err('FINAL_SIZE_ERROR',fs)
            cand=max(s.high,end)
            used=self.used-s.high+cand
            if cand>self.lim_stream or used>self.lim_conn: raise Err('FLOW_CONTROL_ERROR',fs)
            if s.reset is None: s.bytes.insert(f.off,f.data,fs)
            if f.fin and s.final is None: s.final=end
            if cand!=s.high: self.used=used; s.high=cand
            return
        if t==0x04:
            s=self.resolve(f.sid,True,fs)
            if s.final is not None and s.final!=f.final: raise Err('FINAL_SIZE_ERROR',fs)
            if f.final<s.high: raise Err('FINAL_SIZE_ERROR',fs)
            cand=max(s.high,f.final)
            used=self.used-s.high+cand
            if cand>self.lim_stream or used>self.lim_conn: raise Err('FLOW_CONTROL_ERROR',fs)
            s.final=f.final
            if s.reset is None: s.reset=f.err
            if cand!=s.high: self.used=used; s.high=cand
            return
        if t==0x05:
            s=self.resolve(f.sid,False,fs)
            if s.stop is None: s.stop=f.err
            return
        if t==0x11:
            s=self.resolve(f.sid,False,fs)
            s.sendmax=max(s.sendmax,f.v); return
        if t==0x15:
            self.resolve(f.sid,True,fs); return
        if t==0x10: self.smd=max(self.smd,f.v); return
        if t==0x12: self.sms[0]=max(self.sms[0],f.v); return
        if t==0x13: self.sms[1]=max(self.sms[1],f.v); return
        if t==0x18:
            known=self.peermap.get(f.seq)
            if known is not None:
                if known!=(bytes(f.cid),bytes(f.token)): raise Err('PROTOCOL_VIOLATION',fs)
            else:
                for pc in self.peermap.values():
                    if pc[0]==f.cid: raise Err('PROTOCOL_VIOLATION',fs)
            old=self.rpt; new=max(old,f.rpt); fresh=known is None
            if new>old:
                removed=sum(1 for s in self.peermap if old<=s<new)
                self.rpt=new; self.active-=removed
            if fresh:
                self.peermap[f.seq]=(bytes(f.cid),bytes(f.token))
                if f.seq>=self.rpt: self.active+=1
            if self.active>self.lim_cids: raise Err('CONNECTION_ID_LIMIT_ERROR',fs)
            return
        if t==0x19:
            if f.v>=len(self.local) or f.v==dcidseq: raise Err('PROTOCOL_VIOLATION',fs)
            self.retired.add(f.v)
            return
        return

    # ---------------- canonical
    def canonical(self,env,pn,expected,frames):
        body=b''.join(encode_frame(f) for f in frames)
        w=self.pnwidth(pn,expected)
        pnbytes=pn.to_bytes(8,'big')[8-w:]
        if env['level']==2:
            return bytes([0x40|(env['phase']<<2)|(w-1)])+env['dcid']+pnbytes+body
        head=bytes([(0xc0 if env['level']==0 else 0xe0)|(w-1)])+b'\0\0\0\1'
        head+=bytes([len(env['dcid'])])+env['dcid']+bytes([len(env['scid'])])+env['scid']
        if env['level']==0: head+=venc(len(env['token']))+env['token']
        head+=venc(w+len(body))
        return head+pnbytes+body

    @staticmethod
    def pnwidth(pn,expected):
        for w in range(1,5):
            if Trace.reconstruct(pn&((1<<(8*w))-1),w,expected)==pn: return w
        return 4

    # ---------------- output
    def output(self):
        def ivs(merged): return [[a,b] for a,b in merged]
        streams=[]
        for sid in sorted(self.streams):
            s=self.streams[sid]; st=s.bytes
            streams.append(dict(id=sid,high=s.high,final=s.final,reset=s.reset,stop=s.stop,send_max=s.sendmax,
                ranges=ivs(st.merged()),unique=st.unique(),prefix=st.prefix(),sha256=sha(st.prefix_bytes())))
        crypto=[]
        for l in LEVELS:
            st=self.crypto[l]
            crypto.append(dict(level=l,ranges=ivs(st.merged()),unique=st.unique(),prefix=st.prefix(),sha256=sha(st.prefix_bytes())))
        acks=[]
        for l in LEVELS:
            iv=sorted(self.ack[l])
            merged=[]
            for a,b in iv:
                if merged and a<=merged[-1][1]: merged[-1][1]=max(merged[-1][1],b)
                else: merged.append([a,b])
            count=sum(b-a for a,b in merged)
            prefix=merged[0][1] if merged and merged[0][0]==0 else 0
            h=b''.join(a.to_bytes(8,'big')+b.to_bytes(8,'big') for a,b in merged)
            acks.append(dict(level=l,count=count,intervals=len(merged),prefix=prefix,sha256=sha(h),ecn=self.ecn[l]))
        peercids=[dict(sequence=s,id=c[0].hex(),token=c[1].hex()) for s,c in sorted(self.peermap.items()) if s>=self.rpt]
        rl=[]
        for s in sorted(self.retired):
            if rl and s==rl[-1][1]: rl[-1][1]=s+1
            else: rl.append([s,s+1])
        return dict(packets=self.packets,datagrams=self.datagrams,closed=self.closed,
            keys=[l for l in LEVELS if self.keys[l]],
            received={l:self.largest[l] for l in LEVELS},key_epoch=self.cur,
            epochs=[dict(epoch=e,min=v[0],max=v[1],count=v[2]) for e,v in sorted(self.epochs.items())],
            opened=dict(bidi=self.open_bidi,uni=self.open_uni),used=self.used,send_max_data=self.smd,
            send_max_streams=dict(bidi=self.sms[0],uni=self.sms[1]),streams=streams,crypto=crypto,
            acknowledged=acks,peer_cids=peercids,retire_prior_to=self.rpt,retired_local=rl)

def audit(tr):
    return Trace(tr).run()

def batch(obj):
    return {'traces':[audit(t) for t in obj['traces']]}
